/*
 * A042233  Denominators of continued fraction convergents to sqrt(642).
 * https://oeis.org/A042233
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, frac, easy
 * Formula:   Denominators of continued fraction convergents to sqrt(642)
 * Range:     u8 n <= 1, u16 n <= 8, u32 n <= 14, u64 n <= 29, u128 n <= 58,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* a(n) generated by the recurrence stemming from the continued fraction
   expansion of sqrt(642).  The recurrence for the denominators q_k is
   q_k = a_k * q_{k-1} + q_{k-2} with initial values q_{-2}=1,
   q_{-1}=0.  The partial quotients a_k are produced by the standard
   algorithm for sqrt(642). */

seq_t a(idx_t n)
{
    /* constants for sqrt(642) */
    const seq_t a0 = 25;   /* floor(sqrt(642))          */
    const seq_t S  = 642;  /* the radicand              */

    /* Handle the very first term explicitly. */
    if (n == 0) return (seq_t)1;

    /* q_{-2} = 1, q_{-1} = 0  (sentinel values) */
    seq_t q_prev2 = 1;
    seq_t q_prev1 = 0;
    seq_t q_curr;

    /* State of the continued‑fraction algorithm */
    seq_t m = 0;
    seq_t d = 1;
    seq_t a_k = a0;      /* a_0 */

    for (idx_t k = 0; k <= n; ++k) {
        /* Compute the k‑th denominator q_k */
        q_curr = a_k * q_prev1 + q_prev2;
        if (k == n) return q_curr;

        /* Shift the last two denominators for the next step */
        q_prev2 = q_prev1;
        q_prev1 = q_curr;

        /* Advance to the next partial quotient a_{k+1} */
        seq_t m_next = d * a_k - m;
        seq_t d_next = (S - m_next * m_next) / d;
        seq_t a_next = (a0 + m_next) / d_next;

        m = m_next;
        d = d_next;
        a_k = a_next;
    }

    /* Unreachable, but keeps the compiler happy */
    return q_curr;
}
